 "content": "def transform(grid):
    """Overlay four equal panels, resolving occupied cells in panel priority order."""
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    separators = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    bounds = [-1] + separators + [w]
    panels = [list(range(bounds[i] + 1, bounds[i + 1])) for i in range(len(bounds) - 1)]
    if len(panels) != 4 or len({len(p) for p in panels}) != 1:
        raise ValueError("expected four equal-width panels separated by color 3")
    # At each aligned coordinate, the third panel has priority, then the
    # fourth, first, and second panels. Keep the selected panel's color.
    priority = (2, 3, 0, 1)
    out = [[0] * len(panels[0]) for _ in range(h)]
    for r in range(h):
        for c in range(len(panels[0])):
            for p in priority:
                value = grid[r][panels[p][c]]
                if value != 0:
                    out[r][c] = value
                    break
    return out

